// Writes docs/bot-templates.md: every customer-facing message in both languages (sample values), for Nabil to review.
// Usage: npx tsx src/scripts/print-templates.ts > docs/bot-templates.md
import { T, render, type TemplateName } from "../bot/arabic.js";
import { sampleParams } from "../bot/template-samples.js";

const out: string[] = [
  "# Bot message templates",
  "",
  "Generated by `src/scripts/print-templates.ts` from `src/bot/arabic.ts` (object `T`, one entry per intent, comments there say when each is used).",
  "Sample values are fake. Prices are never mentioned. At most ONE message is sent per customer turn.",
  "",
];
for (const name of Object.keys(T) as TemplateName[]) {
  out.push(`## ${name}`, "");
  for (const lang of ["ar", "en"] as const) {
    const text = (render as (l: string, n: string, p: unknown) => string)(lang, name, sampleParams(lang));
    out.push(`**${lang}:**`, ...text.split("\n").map((l) => `> ${l}`), "");
  }
}
console.log(out.join("\n"));
